/**
 * Single source of truth for CONTRACTS §0 file ownership.
 * Consumed by check-ownership.mjs (CLI) and guard.mjs (PreToolUse hook).
 * Lead-owned — agents do not edit this file.
 */

export const AGENTS = ['data', 'backend', 'design', 'frontend'];

/** Paths only the lead may touch, whoever is asking. */
export const LEAD_ONLY = [
  /^types\/contracts\.ts$/,
  /^types\/index\.ts$/,
  /^docs\/agents\/CONTRACTS\.md$/,
  /^docs\/agents\/README\.md$/,
  /^package(-lock)?\.json$/,
  /^app\.json$/,
  /^lib\/supabase\.ts$/,
  /^CLAUDE\.md$/,
  /^vitest\.config\.ts$/,
  /^supabase\/config\.toml$/,
  /^scripts\/agents\//,
  /^\.claude\/settings\.json$/,
  // Already applied to the remote project — nobody edits these.
  /^supabase\/migrations\/00[1-5]_/,
];

/** What each agent may write. Reading anything is always fine. */
export const OWNED = {
  data: [
    /^supabase\/migrations\/(0(0[6-9]|[1-9]\d)|[1-9]\d\d)_.*\.sql$/,
    /^supabase\/seeds\//,
    /^supabase\/tests\//,
    /^scripts\/content\//,
    /^content\//,
    /^docs\/runbooks\//,
  ],
  backend: [
    /^supabase\/functions\//,
    /^lib\//, // minus lib/supabase.ts, which LEAD_ONLY catches first
  ],
  design: [
    /^components\//,
    /^constants\/Colors\.ts$/,
    /^docs\/design\//,
    /^assets\//,
  ],
  frontend: [
    /^app\//,
    /^hooks\//,
    /^context\//,
    /^_screens_auth\//,
  ],
};

/** Shell commands no agent may run — they reach the remote project or the network. */
export const FORBIDDEN_COMMANDS = [
  { re: /\bsupabase\s+db\s+push\b/, why: 'pushes migrations to the REMOTE Supabase project' },
  { re: /\bsupabase\s+link\b/, why: 'links this worktree to the remote Supabase project' },
  { re: /\bsupabase\s+functions\s+deploy\b/, why: 'deploys Edge Functions to the remote project' },
  { re: /\bsupabase\s+secrets\b/, why: 'reads or writes remote project secrets' },
  { re: /\bsupabase\s+projects\b/, why: 'manages remote Supabase projects' },
  { re: /\bgit\s+push\b/, why: 'pushes a branch; the lead merges and pushes, not you' },
  { re: /\bgh\s+(pr|repo|release)\b/, why: 'acts on GitHub; the lead does that' },
  { re: /\bnpm\s+(i|install|uninstall|add)\b(?!.*--dry-run)/, why: 'changes dependencies — package.json is lead-owned. Request the dependency in your status file' },
  { re: /\b(yarn|pnpm|bun)\s+(add|install|remove)\b/, why: 'changes dependencies — package.json is lead-owned' },
  { re: /\bnpx\s+expo\s+install\b/, why: 'changes dependencies — package.json is lead-owned' },
];

/** Which agent a working directory belongs to; null for the lead checkout. */
export function agentFromDir(dir) {
  const name = (dir || '').split('/').filter(Boolean).pop() || '';
  const m = /^el-(data|backend|design|frontend)$/.exec(name);
  return m ? m[1] : null;
}

/** `null` if the write is allowed, otherwise the reason it is not. */
export function ownershipViolation(agent, relPath) {
  const p = relPath.replace(/^\.\//, '');
  if (p === `docs/agents/status/${agent}.md`) return null;
  if (/^docs\/agents\/status\//.test(p)) return `${p} is another agent's status file`;
  if (LEAD_ONLY.some((re) => re.test(p))) return `${p} is lead-owned`;
  const owned = OWNED[agent] || [];
  if (owned.some((re) => re.test(p))) return null;
  const owner = AGENTS.find((a) => (OWNED[a] || []).some((re) => re.test(p)));
  return owner ? `${p} belongs to the ${owner} agent` : `${p} is outside your owned paths`;
}
